package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="billing_invoices") public class BillingInvoice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=40) private String invoiceNumber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="patient_id",nullable=false) private User patient; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="appointment_id") private Appointment appointment; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Column(nullable=false,length=30) private String status="ISSUED"; private LocalDateTime issuedAt; public BillingInvoice(){} public BillingInvoice(String n,User p,Appointment a,BigDecimal amount){invoiceNumber=n;patient=p;appointment=a;this.amount=amount;} @PrePersist void c(){issuedAt=LocalDateTime.now();} public Long getId(){return id;} public String getInvoiceNumber(){return invoiceNumber;} public User getPatient(){return patient;} public Appointment getAppointment(){return appointment;} public BigDecimal getAmount(){return amount;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getIssuedAt(){return issuedAt;} }
